# >>> STATIC
_static_cms_u() {
    cat <<-'ARGCEOF'
	0	certUsageSSLClient
	1	certUsageSSLServer
	2	certUsageSSLServerWithStepUp
	3	certUsageSSLCA
	4	certUsageEmailSigner
	5	certUsageEmailRecipient
	6	certUsageObjectSigner
	7	certUsageUserCertImport
	8	certUsageVerifyCA
	9	certUsageProtectedObjectSigner
	10	certUsageStatusResponder
	11	certUsageAnyCA
ARGCEOF
}

_static_verify_cert_R() {
    cat <<-'ARGCEOF'
	ocsp	Check revocation status using OCSP method
	require	Require a positive response for successful verification
	offline	Consult cached responses only (no network requests)
ARGCEOF
}

_static_filevault_skip_sc_enforcement_operation() {
    cat <<-'ARGCEOF'
	set	Sets SmartCard enforcement to be skipped for the next boot
	reset	Resets any SmartCard overrides
	status	Tells the current state of the SmartCard overrides
ARGCEOF
}
# <<< STATIC

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_allowed_error() {
    echo certExpired
    echo hostnameMismatch
}

_choice_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_command_args() {
    if [[ "${#argc__positionals[@]}" -lt 2 ]]; then
        _choice_command
    else
        _argc_util_comp_subcommand 0
    fi
}

_choice_keychain() {
    security list-keychains 2>/dev/null | sed -E 's/^[[:space:]]*"?//; s/"[[:space:]]*$//'
}

_choice_rulename() {
    echo allow
    echo deny
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
